        "html": "<p>플로렌스 나이팅게일(1820~1910)은 '등불을 든 여인'이기 이전에 19세기의 탁월한 통계학자이자 데이터 시각화의 선구자였다. 크림 전쟁(1853~1856) 당시 스쿠타리 군 병원에서 병사들의 사망 원인을 체계적으로 수집·분석하여, 전투 사망자보다 비위생적 환경으로 인한 감염병 사망자가 훨씬 많음을 밝혀냈다. 그녀가 개발한 <b>'폴라 에어리어 다이어그램(장미 그래프)'</b>은 정치가와 관료들을 설득해 군 병원 위생 개혁과 사망률의 극적 감소를 이끌어냈다. 이는 자료(Data)→정보(Information)→지식(Knowledge)→지혜(Wisdom)로 이어지는 DIKW 모델의 원형으로, 150여 년 전에 이미 '데이터 기반 간호'가 실천된 사례이다.</p><p>이 유산은 1970년대 병원정보시스템(HIS), 1990년대 전자의무기록(EMR), 2000년대 디지털 헬스를 거치는 디지털전환(DX)으로 이어졌고, 2020년대에는 AI가 의사결정 자체를 변화시키는 AI전환(AX)이 시작되었다.</p><table><tr><th>구분</th><th>디지털전환(DX)</th><th>AI전환(AX)</th></tr><tr><td>핵심 기술</td><td>컴퓨터, 인터넷, 모바일, 클라우드</td><td>머신러닝, 딥러닝, 생성형 AI, LLM</td></tr><tr><td>보건의료 예시</td><td>EMR 도입, 처방전달시스템(OCS) 구축</td><td>AI 패혈증 조기경보, 생성형 AI 간호 기록 보조</td></tr><tr><td>의사결정 방식</td><td>데이터를 디지털화, 인간이 판단</td><td>AI가 패턴 인식·예측, 인간이 최종 승인</td></tr><tr><td>간호사 역할 변화</td><td>키보드로 기록하는 간호사</td><td>AI 출력을 비판적으로 검토하는 임상 전문가</td></tr><tr><td>현재 상태(한국)</td><td>EMR 보급률 거의 100%(상급종합병원)</td><td>혁신의료기기 45개 지정(식약처, 2025)</td></tr></table><p>DX와 AX는 대체 관계가 아니라 <b>누적 관계</b>다. 표준화된 EMR 등 탄탄한 디지털 인프라 없이 AI는 작동할 수 없으므로, 간호사는 '정확한 데이터 입력·관리'(DX)와 'AI 출력의 비판적 검증'(AX) 모두를 이해해야 한다.</p>"
