        "html": "<p>간호정보전문가(INS: Informatics Nurse Specialist)는 간호 임상 실무 역량과 정보학 전문 역량을 겸비하여 정보 시스템의 설계·구현·평가·교육을 주도하는 전문 간호사로, 임상 현장의 언어와 기술의 언어를 모두 이해하는 가교 역할을 한다. AMIA는 INS를 ICT 개발자, 교육자, 연구자, 최고간호정보책임자(CNIO), CIO, 구현 컨설턴트, 정책 개발자 등으로 의료 발전에 기여하는 전문가로 정의한다.</p><ul><li><b>임상 시스템 분석가:</b> EMR·HIS 도입·유지보수, 임상 워크플로우 분석(임상 경험 + 시스템 분석)</li><li><b>간호정보교육자:</b> EMR·AI 도구 활용 교육, 디지털 역량 개발(교육 설계 + 임상 지식)</li><li><b>최고간호정보책임자(CNIO):</b> 병원 디지털 전략 수립, 간호 IT 예산 관리(리더십 + 전략적 사고)</li><li><b>AI 임상 구현 전문가:</b> AI 의료기기 임상 검증, 알고리즘 편향 모니터링(AI 이해 + 임상 평가)</li><li><b>간호연구-정보학 전문가:</b> 간호 데이터 분석, NLP 기반 기록 연구(연구 방법론 + 데이터 과학)</li></ul><p>국제 공인 자격증은 ANCC의 <b>NI-BC</b>(1995년 최초 시행)이며, 한국에서도 응시 가능하다.</p><table><tr><th>항목</th><th>내용</th></tr><tr><td>자격 조건</td><td>현행 RN 면허 / 최근 3년간 2년 이상 임상 경력 / 최근 3년간 2,000시간 이상 간호정보학 실무 / 30학점 이상 계속 교육</td></tr><tr><td>시험 구성</td><td>총 150문항(채점 125 + 비채점 pretest 25), 4지선다, 3시간, Prometric 시험센터 응시</td></tr><tr><td>시험 내용 비중</td><td>실무의 기초 36%(약 45문항) / 시스템 설계·개발 수명주기 35%(약 44문항) / 데이터 관리 및 의료 기술 29%(36문항)</td></tr><tr><td>합격률·갱신</td><td>합격률 약 66%, 5년마다 갱신(계속 교육 또는 재시험)</td></tr></table><p>지금 이 교재의 학습이 NI-BC 준비의 첫걸음이며, 졸업 후 EMR 슈퍼유저·디지털 전환 프로젝트 참여 등의 경력으로 자격 조건을 충족할 수 있다.</p>"
