      {
        "q": "프롬프트 엔지니어링을 '잘 한다'는 것이 구체적으로 무엇을 의미하나요? 임상 예시로 설명해주세요.",
        "a": "프롬프트 엔지니어링을 잘 한다는 것은 네 가지 요소를 갖추는 것입니다. (1) 역할 부여: '경험 많은 감염내과 간호사로서 답변해줘'처럼 AI에게 전문 맥락을 설정합니다. (2) 구체적 맥락 제공: 환자 연령, 진단명, 현재 상황을 명시합니다. (3) 출력 형식 지정: '표 형식으로', '5줄 이내로', 'SBAR 형식으로'처럼 원하는 형태를 요청합니다. (4) 제약 조건 설정: '처방전 없이 시행 가능한 중재만', '소아 용량은 제외'처럼 범위를 한정합니다. 나쁜 예: '패혈증 간호 뭐야?' / 좋은 예: '65세 만성신부전 환자의 패혈증 초기 대응에서 간호사가 독자적으로 수행할 수 있는 1시간 이내 중재를 우선순위 순으로 5가지 제시해줘. 각 중재에 대해 근거 가이드라인과 모니터링 항목을 포함해줘.'"
      },
      {
        "q": "생성형 AI를 환자 교육 자료 작성에 활용할 때 개인정보보호법 위반 우려가 있지 않나요?",
        "a": "정확히 짚은 중요한 문제입니다. 실제 환자의 이름, 주민등록번호, 진단명 등 개인식별정보를 AI에 입력하는 것은 개인정보보호법 제23조(민감정보 처리 제한) 위반 소지가 있습니다. 안전한 활용 방법은 두 가지입니다. (1) 익명화: 실제 환자 정보 대신 '58세 남성, 당뇨 병력 10년'처럼 일반화된 정보만 입력합니다. (2) 병원 전용 AI 플랫폼 사용: 일부 병원에서는 개인정보보호 계약이 체결된 병원 내부 AI 시스템을 구축합니다. 이 경우 승인된 데이터만 처리됩니다. 상용 AI 서비스(ChatGPT, Gemini 등)는 개인정보보호 계약 체결 없이는 환자 식별정보 입력을 피해야 합니다. 이것이 E(윤리성) 검증의 핵심 항목 중 하나입니다."
      },
      {
        "q": "간호정보전문가(INS)가 되려면 어떤 진로 경로를 밟아야 하나요?",
        "a": "일반적인 한국 간호사의 INS 경력 경로는 다음과 같습니다. (1) 임상 경력 기반 구축(1~3년): 일반 병동 또는 중환자실에서 EMR 숙련도를 높이고, 병원의 디지털 전환 프로젝트에 자원합니다. (2) 슈퍼유저 역할(3~5년): EMR 도입·업데이트 시 해당 부서의 슈퍼유저(핵심 사용자)로 활동하며 시스템 구현 경험을 쌓습니다. (3) 대학원 진학 또는 전문 교육: 보건의료정보관리학, 의료정보학 관련 대학원 과정 이수, 또는 관련 자격증(의료정보사, CPHIMS 등) 취득. (4) ANCC NI-BC 응시: 요건(RN, 2000시간 이상 NI 실무)을 충족하면 ANCC 공식 사이트에서 신청합니다. (5) 전문 역할로 전환: CNO(최고간호책임자), CNIO, 병원 정보 시스템 PM 등으로 경력을 발전시킵니다."
      },
      {
        "q": "디지털 리터러시, 정보 리터러시, AI 리터러시 중 현재 간호사에게 가장 부족한 것은 무엇인가요?",
        "a": "세 가지 모두 부족하지만, 연구 문헌은 AI 리터러시의 격차가 가장 급격하게 확대되고 있음을 보여줍니다. El Arab 등(2025)의 PRISMA 체계적 문헌 고찰(37편 연구, Frontiers in Digital Health)에 따르면 간호사와 간호학생 모두 AI에 대해 중간 수준의 긍정적 태도를 보이지만, AI 리터러시와 준비도는 '보통(Moderate)' 수준에 머물러 있습니다. 특히 'AI가 일상 업무에서 인간을 능가할 수 없다'는 인식이 강했는데, 이는 AI를 과소평가하거나 과대평가하는 이분법적 인식의 표현입니다. 전문 교육을 받을수록, 컴퓨터 활용 능력이 높을수록 AI 리터러시가 향상되었습니다. 즉, 이 수업이 바로 격차를 줄이는 직접적 개입입니다. 제2장"
      }
