      "전자의무기록(EMR), 전자건강기록(EHR), 개인건강기록(PHR)의 개념적 차이를 정의하고, 한국 진료정보교류사업의 현황과 한계를 비판적으로 평가할 수 있다. (이해·분석·평가)",
