        "title": "교육용 HMS와 핸즈온 실습: AI를 활용한 가상 환자 시나리오 분석",
        "html": "<p>교육용 병원 관리 시스템(HMS)은 AI융합 간호정보학 및 임상 의사결정 시뮬레이션 실습을 위해 자체 제작한 시스템(Node.js·Bootstrap 5·Chart.js 기반)으로, 접수→진료 예약→진료·처방→청구·수납→간호 기록→보고서 분석으로 이어지는 OCS·EMR 연동 워크플로우 전 과정을 모사한다. 관리자·의사·간호사 역할별 로그인으로 권한을 실습하며, 핵심 교육 기능은 ①<b>DIKW 모델 실시간 추적기</b>(데이터→정보→지식→지혜의 가치 변환을 화면 하단에 시각화) ②<b>CDSS 시뮬레이터</b>(페니실린 알레르기 환자에게 유해 약물 처방 시 경고) ③원스톱 병원 행정 흐름 학습이다.</p><div class=\"callout info\"><b>🖥️ 실습 1: AI 기반 가상 환자 사정 보조(20분)</b> — 가상 환자 김OO(남, 72세, 복강경 담낭 절제술 후 2일차, 2형 당뇨 12년·고혈압 8년·만성 신장질환 3기, 페니실린 알레르기-아나필락시스 기왕력). 활력징후가 6시간 동안 T 36.8→38.2, P 78→112, BP 128/82→92/60, SpO₂ 98→93%로 악화, WBC 14,200, Lactate 2.8 mmol/L, Creatinine 2.1(baseline 1.4), Procalcitonin 2.3, 혈액배양 결과 대기 중, 오한 호소·피부 창백·말초 냉감. 이 데이터를 AI에 입력해 ①가장 긴박한 임상 문제와 근거 ②우선순위 간호 중재 5가지(독자 수행/의사 지시 구분) ③SBAR 보고서 초안을 요청한 뒤, TRACE로 검증한다(Sepsis-3 기준 일치 여부, 1-Hour Bundle 최신성, 젖산 정상치 &lt;2 mmol/L, 신기능 저하 용량 조정·페니실린 알레르기 고려 여부, 혈액배양 대기 반영, 환자 자율성 존중 언어). <b>제출:</b> TRACE 항목별 문제점 최소 3가지 + 수정·보완된 최종 SBAR 보고서</div><div class=\"callout info\"><b>🖥️ 실습 2: 경고 피로 시나리오 분석(15분)</b> — 간호사 윤OO이 오전 4시간 동안 받은 경보 37건(투약 알레르기 12건 중 의사가 이미 확인한 11건, 활력징후 이상 15건 중 기저 수치 고려 시 실제 이상 없는 13건, 낙상 재평가 7건 중 중복 4건, 패혈증 예측 3건 중 실제 고위험 1건). AI에게 경고 피로 원인 분석과 환자 안전을 유지하며 부담을 줄일 전략 3가지, CDSS 운영팀 제출용 경보 개선 건의서 초안(200자 이내)을 요청하고, 제안의 실행 가능성을 평가한다. <b>제출:</b> AI 전략 평가(실행 가능/불가능 + 이유) + 보완된 개인 전략 1가지</div>"
