        "a": "분당서울대병원의 100% 디지털화는 단일 병원 내부의 성공 사례입니다. 문제는 병원 간 상호운용성입니다. A병원의 EMR 시스템과 B병원의 EMR이 서로 다른 데이터 구조·용어·인터페이스를 사용하면, 디지털화되어 있어도 데이터를 교환할 수 없습니다. 이것이 '사일로(Silo)' 문제입니다. 한국은 의원급 의료기관까지 포함하면 수천 개의 서로 다른 EMR 시스템이 존재합니다. HL7 FHIR 표준을 도입하더라도 기존 시스템 전환 비용, 병원의 참여 유인 부족, 개인정보 보호 우려 등 현실적 장벽이 존재합니다. EMR 인증제와 진료정보교류사업은 이 장벽을 단계적으로 극복하는 정책 수단입니다. 제3장"
