        "title": "개요: 지식이 넘치는 시대, 간호사에게 필요한 것",
        "html": "<p>4장에서 우리는 간호 데이터가 표준화되어야 AI가 제대로 작동할 수 있음을 배웠습니다. 이제 5장에서는 그 AI — 특히 생성형 AI(Generative AI) — 를 임상 지식 관리와 실무에서 어떻게 활용할 것인지를 탐구합니다. 오늘날 의료 지식은 하루에도 수천 편의 새로운 논문과 가이드라인이 쏟아지는 속도로 증가합니다. PubMed에는 3,700만 건 이상의 문헌이 등재되어 있고 매년 수십만 건이 추가됩니다. 인간이 이를 모두 읽고 소화하는 것은 불가능합니다.</p><p>이 지식의 홍수 속에서 두 가지 핵심 역량이 요구됩니다. 첫째, '어떤 지식이 가장 신뢰할 수 있는가?'를 비판적으로 평가하는 <b>근거기반실무(EBP) 역량</b>입니다. 둘째, 생성형 AI를 강력한 보조 도구로 활용하면서도 그 한계를 정확히 이해하는 <b>AI 리터러시 역량</b>입니다. 두 역량은 대체 관계가 아니라 통합적 관계입니다 — EBP가 '무엇을 알아야 하는가'를 안내하고, 생성형 AI가 '더 빠르고 효율적으로 알 수 있도록' 보조합니다.</p><p>이 장에서는 3·4장에서 이어진 72세 김OO 환자 사례를 <b>퇴원 후 맥락</b>으로 연결합니다. 자가 관리가 필요한 이 환자를 위해 어떻게 근거를 찾고, AI로 교육자료를 만들며, 간호 기록을 효율적으로 작성하는지 실습으로 직접 경험합니다.</p><div class=\"callout info\"><b>💬 1분 활동: 지식 검색 경험 나누기</b><br>임상 실습 중 '이 처치가 정말 최신 근거에 맞는 걸까?' 궁금했던 순간이 있었나요? 그때 어떻게 답을 찾았나요 — 교과서? 선배 간호사? 인터넷 검색? ChatGPT? 각 방법의 장단점을 짝과 1분간 비교하고, EBP가 필요한 이유를 자신의 언어로 정리해 보세요.</div>"
