        "html": "<p>EBP는 전문가의 임상 판단, 최선의 연구 근거, 환자의 가치관을 통합하는 의사결정 체계입니다. 5단계 프로세스 각각에서 AI의 보조 역할과 인간 고유 영역이 구분됩니다.</p><ol><li><b>Ask</b> — PICO 구성: AI가 초안 작성 보조 → 간호사가 임상 맥락에 맞게 수정</li><li><b>Acquire</b> — 검색: AI가 Boolean·MeSH 전략 제안 → 간호사가 PubMed 직접 검색</li><li><b>Appraise</b> — 비판적 평가: AI 보조 최소 (근거 위계·임상 적용성 = 인간 전문 판단)</li><li><b>Apply</b> — 적용: AI가 중재 초안 작성 → 간호사가 환자 맥락에 맞게 개인화</li><li><b>Assess</b> — 평가: AI가 데이터 정리 보조 → 간호사가 임상적 해석·기록</li></ol><h4>PICO: 임상 질문의 구조화</h4><ul><li><b>P</b> Patient/Population — 어떤 환자군인가?</li><li><b>I</b> Intervention — 어떤 중재·진단·예후 요인인가?</li><li><b>C</b> Comparison — 비교 대상 (없을 수도 있음)</li><li><b>O</b> Outcome — 원하는 결과·성과는 무엇인가?</li></ul><div class=\"callout info\"><b>📋 김OO 연속 사례 PICO (퇴원 후 맥락)</b><br>P: 복강경 수술 후 패혈증 회복 70세 이상 당뇨 남성 / I: 간호사 주도 퇴원 후 원격 추적 관찰(전화·앱) / C: 일반적 외래 방문 추적 / O: 30일 내 재입원율 감소</div><p><b>PubMed Boolean 연산자</b>: AND(교집합·결과 축소) · OR(유의어 확장·결과 증가, 예: fall OR accidental fall) · NOT(특정 개념 제외)</p><div class=\"callout warn\">🚫 AI가 대체 불가한 영역: 3단계 비판적 평가와 환자 가치관 통합. 근거 위계(체계적 문헌고찰 &gt; RCT &gt; 코호트 &gt; 단면 &gt; 전문가 의견) 판단은 인간 전문가의 몫입니다.</div>"
