        "html": "<h4>LLM은 어떻게 작동하는가 — 간호사가 알아야 할 핵심</h4><p>대규모 언어 모델(LLM)은 Transformer 아키텍처를 기반으로 방대한 텍스트에서 언어 패턴을 학습하여, 입력(토큰)에 대해 통계적으로 가장 그럴듯한 다음 내용을 생성합니다. 이 원리 때문에 LLM은 '사실'이 아니라 '그럴듯함'을 생성하며, 여기서 환각(Hallucination)이 발생합니다. 코딩 지식이 아니라 이 개념적 이해가 임상 검증의 출발점입니다.</p><h4>RAG(검색증강생성): 환각을 줄이는 핵심 기술</h4><ul><li><b>정의</b>: LLM이 답을 생성하기 전 외부 지식 베이스에서 관련 정보를 먼저 검색하고, 이를 참고하여 생성하는 방식</li><li><b>효과</b>: 환각이 유의하게 감소</li></ul><div class=\"callout ok\"><b>NurRAG 연구 (2025)</b><br>RAG 적용 전 정확도 49.08% → 적용 후 <b>75.83%</b> (p&lt;0.001) · ROUGE-L 30.73% → 64.27%</div><p><b>임상 함의</b>: ① 병원 자체 프로토콜·가이드라인을 RAG 지식 베이스로 구성하면 병원 특화 AI 가능 ② AI 출력에 출처가 있으면 RAG 기반, 없으면 순수 LLM — 신뢰도를 차별 평가 ③ RAG도 완벽하지 않으므로 TRACE 검증 원칙은 동일하게 적용</p>"
