        "html": "<h4>간호 기록 부담과 Ambient AI Scribe</h4><p>간호사 업무 시간의 상당 부분이 기록에 소요됩니다. <b>Ambient AI Scribe(음성인식 EMR)</b>는 의료 현장의 대화를 실시간 청취하고 NLP로 임상 기록 초안을 자동 생성하는 기술입니다.</p><div class=\"callout ok\"><b>📋 임상 근거 (2025~2026, 싱가포르 대학병원 연구)</b><br>Ambient AI Scribe 도입 후 기록 시간 감소와 환자와의 아이 컨택 비율 증가가 확인되었습니다 (JMIR Medical Informatics, 2026). 한국어 지원·국내 EMR 연동 현황은 아직 검증이 필요한 단계입니다.</div><h4>SBAR 보고서 작성 보조</h4><p>S(Situation)·B(Background)·A(Assessment)·R(Recommendation) 형식의 인계·보고 초안을 생성형 AI가 작성할 수 있습니다. 단, <b>AI 초안은 반드시 TRACE 검증 후 수정·보완</b>해야 하며, 기록의 최종 책임은 서명하는 간호사에게 있습니다.</p>"
