        "html": "<p>법률 제20139호 · 2025년 1월 24일 시행 · 소관: 식품의약품안전처(MFDS). <b>세계 최초로 디지털 기반 의료제품을 단독 규율하는 법률</b>입니다.</p><ul><li><b>규제 대상 3종</b>: ① 디지털의료기기 ② 디지털융합의약품 ③ 디지털의료·건강지원기기</li><li><b>SaMD(Software as a Medical Device)</b>: 하드웨어 없이 독립 운영되는 소프트웨어 의료기기 (AI 패혈증 예측 앱 등). 별도의 식약처 허가 필요</li><li><b>RWE(Real-World Evidence)</b>: 허가 후 실사용 데이터로 지속적 안전성·유효성 평가</li></ul><div class=\"callout ok\"><b>간호사 관련 핵심 의무 4가지</b><ol><li>사용 전 식약처 허가 여부 확인 (udiportal.mfds.go.kr)</li><li>화면 표시기재 정보(허가번호·사용목적·주의사항) 확인 (2026.1.24.~)</li><li>이상사례(AI 오류·오경보) 발견 시 의료기기 관리팀에 보고</li><li>AI 시스템 접속 시 개인 계정 사용, 로그아웃, 공유 계정 금지</li></ol></div><div class=\"callout info\"><b>📋 연속 사례 적용 — 김OO 패혈증 AI 시스템의 규제 점검</b><br>김OO 환자 병원의 패혈증 AI 조기경보 시스템을 '규제 렌즈'로 점검합니다: 이 시스템은 SaMD로서 식약처 허가를 받았는가? 화면에 허가번호·사용목적이 표시되는가? 오경보 발견 시 보고 체계가 있는가? — 간호사가 확인할 수 있고, 확인해야 하는 항목들입니다.</div>"
