        "html": "<h4>의료정보는 왜 특별히 보호받는가</h4><p>건강·의료정보는 유출 시 회복 불가능한 피해(차별, 사생활 침해)를 낳는 <b>민감정보</b>이기 때문에 일반 개인정보보다 강하게 보호됩니다.</p><ul><li><b>제23조 (민감정보)</b>: 건강·의료정보는 별도 동의 없이 처리 금지</li><li><b>제29조 (안전조치)</b>: 기술적·관리적 보호조치 의무. 계정공유·약한 패스워드 금지</li><li><b>제34조 (유출신고)</b>: 민감정보 유출 시 <b>72시간 내</b> 개인정보보호위원회(PIPC) 또는 KISA 신고</li><li><b>제71조 (벌칙)</b>: 민감정보 불법 처리 시 5년 이하 징역 또는 5천만 원 이하 벌금</li></ul><h4>의료정보 침해 사례 분석</h4><ol><li><b>🇰🇷 17개 종합병원 환자정보 유출 (2023)</b>: 병원·제약사 직원이 처방 정보를 이메일·USB로 유출(185,271건). 16개 병원 과태료. 교훈 — '업무 협조', '상급자 지시', '금전적 이득 없음'은 면책 사유가 아니다.</li><li><b>🇰🇷 EMR 업체 안전조치 위반 (2024)</b>: 외부 접속 시 VPN 미적용, 접속기록 미보관, 다운로드 사유 확인 기능 미제공. 교훈 — 간호사도 병원 공식 VPN으로만 EMR 접속.</li><li><b>🇰🇷 의료기관 랜섬웨어 해킹 (2021~)</b>: 공유 계정, 보안 패치 지연, 피싱 메일 클릭이 주요 원인. 교훈 — 출처 불명 이메일 첨부파일·링크 클릭 절대 금지.</li></ol>"
