        "icon": "📖",
        "title": "개요: ICU — AI의 임상 최전선",
        "html": "<p>7장에서 우리는 AI 의료기기를 규율하는 법과 개인정보보호 의무를 배웠습니다. 이 장에서는 다시 임상 현장으로 돌아옵니다. 모든 장 중에서 AI가 가장 집약적으로 적용되는 곳은 <b>중환자실(ICU)</b>입니다. ICU에서는 분당 수백 건의 생체 신호가 수집되고, AI가 이를 실시간으로 분석하여 패혈증·욕창·섬망·재입원을 예측합니다.</p><p>2025년 발표된 서사적 문헌 고찰(PMC12701216)은 2020~2025년 ICU 간호 AI 연구 4,138편 중 37편을 선별 분석했습니다. 보고된 판별 성능은 대부분 <b>AUC 0.80 이상</b>이었으며, 조기 경보·위험 예측, 간호 의사결정 지원, 문서화 자동화, 자원 배분 최적화가 주요 적용 영역으로 확인되었습니다. 그러나 보정(Calibration), 외부 검증, 인간 요인 평가는 여전히 부족한 상태로 지적되었습니다.</p><div class=\"callout info\"><b>💬 1분 활동: ICU와 AI</b><br>ICU에서 간호사가 담당하는 환자 수는 일반 병동보다 적지만, 관리해야 하는 데이터의 양과 복잡성은 훨씬 많습니다. → ICU에서 AI가 간호사에게 가장 도움이 될 수 있는 상황은? 반대로 AI를 가장 조심스럽게 사용해야 하는 상황은 무엇일까요?</div>"
