        "icon": "🛏️",
        "title": "연속 사례 확장: 김OO 환자의 ICU 전동",
        "html": "<p>3~7장에서 이어온 72세 김OO 환자가 패혈증 치료 중 ICU로 전동되었습니다. ICU Day 2의 핵심 수치를 AI와 함께 해석합니다.</p><ul><li>패혈증 AI 점수: 71점 (↓개선 추세) · Lactate 1.8 mmol/L (↓) · WBC 11,200 (↓)</li><li>욕창 AI: 고위험 — Braden 11점, 부동 48시간, Vasopressin 투여</li><li>섬망 AI: 중등도 위험 — 72세, ICU 2일차, 진정제 사용</li></ul><div class=\"callout ok\"><b>수치 해석 연습 (간호사가 직접 계산·검증)</b><ul><li>MAP = (104 + 2×68) ÷ 3 = <b>80 mmHg</b> → 패혈증 목표(≥65 mmHg) 달성</li><li>소변량 = 40mL/hr ÷ 73kg = <b>0.55 mL/kg/hr</b> → 정상 하한(0.5) 부근의 경계치</li><li>Creatinine 1.9 mg/dL (↑ 지속) → 항생제 용량 조정 필요성 확인</li></ul></div>"
