        "html": "<ul><li><b>NAVOY® Sepsis</b> (Persson 2024): 패혈증 발생 3시간 전 예측, AUROC 0.80, 정확도 79% — 최대 규모 전향 RCT로 검증된 ML 모델</li><li><b>FDA De Novo 승인 (2024.4.)</b>: Prenosis Sepsis ImmunoScore — 패혈증 AI 최초의 FDA 공인</li><li>ICU AI의 역할: 실시간 패혈증 점수 추적, 항생제 스튜어드십 보조, 회복 추적</li></ul><p>AI 점수는 qSOFA·MEWS 같은 단면 점수와 달리 활력징후·검사·기록을 <b>연속적으로 통합 분석하는 동적 예측</b>입니다. 다만 기존 점수를 대체하는 것이 아니라 보완하며, 간호사는 점수의 의미를 임상 맥락에서 해석하고 직접 사정으로 검증합니다.</p>"
