        "html": "<h4>ICU 욕창(HAPI)의 특수성</h4><p>ICU의 HAPI(병원획득 욕창) 유병률은 16.9~23.8%, 발생률은 10.0~25.9%에 달합니다. 부동, 승압제 사용, 영양 저하, 진정 상태가 복합 작용하기 때문입니다.</p><h4>AI 욕창 예측의 임상 근거 — Braden Scale 대비 우위</h4><ul><li><b>우위 ①</b>: 분 단위 연속 평가 (Braden은 12~24시간 간격)</li><li><b>우위 ②</b>: 다변수 통합 (BUN·알부민·vasopressor·소변량 등 Braden에 없는 변수 포함)</li></ul><div class=\"callout warn\">AI 고위험 경보는 '지금 가서 직접 피부를 확인하라'는 신호입니다. Braden Scale의 구조화된 직접 사정과 AI의 연속 모니터링은 대체가 아닌 보완 관계입니다.</div>"
