        "icon": "📖",
        "title": "개요: 병동 뒤편의 AI — 행정·운영의 혁신",
        "html": "<p>8장에서는 침상 옆 임상 현장에서 AI가 어떻게 활용되는지를 살펴보았습니다. 이 장에서는 병원 운영의 '뒤편' — 간호인력 배치, 병상 가동률 관리, 의료 물류, 스마트 병동 환경 — 에서 AI가 어떤 역할을 하는지 탐구합니다.</p><p>간호행정은 직접 간호 업무에 비해 덜 주목받지만, <b>간호 결과를 결정하는 핵심 구조</b>입니다. 잘못 배치된 인력, 빈번한 초과근무, 예측 불가능한 병상 수요, 물류 지연은 모두 환자 안전과 간호사 번아웃에 직접 영향을 미칩니다.</p><p>2025년 OJIN 리뷰(Rony 등)에 따르면 AI 기반 동적 인력 배치(Dynamic Staffing)는 응급실처럼 예측이 어려운 환경에서 환자 볼륨 예측, 대기 시간 감소, 스태프 번아웃 방지에 기여하고 있습니다. 미국 AI 간호 스케줄링 소프트웨어 시장은 2024년 5,558만 달러 → 2033년 5억 1,641만 달러로 <b>연평균 28.4% 성장</b>이 예측됩니다 (Grand View Research, 2025).</p><div class=\"callout info\"><b>💬 1분 활동: 병동 스케줄링의 현실</b><br>병동의 간호사 스케줄이 어떻게 결정되는지 본 적 있나요? 수간호사가 수작업으로 표를 만들며 간호사들의 요청과 병원 수요를 맞추는 데 얼마나 많은 시간과 갈등이 발생하는지 — 이 문제를 AI가 해결한다면 어떤 이점과 위험이 있을까요?</div>"
