        "a": "96.7%는 최적 병상 가동률(80~85%)을 현저히 상회하는 수준입니다. 구체적인 문제는 세 가지입니다. 첫째, 응급 환자 수용 불가 위험: 응급 환자가 급증할 경우 즉시 입원시킬 빈 병상이 없어 응급실 체류가 길어집니다. 둘째, 감염 관리 위험: 병상 밀도가 높아지면 접촉 감염 위험이 증가합니다. 셋째, 간호 질 저하: 간호사 1인당 담당 환자 수가 증가하여 개별 환자에게 할애할 시간이 줄어듭니다. 실습 시나리오에서는 이를 고려하여 오전 배치를 4명으로 조정해야 하며(패혈증 회복기 6명 + 신규 입원 예상), 초과 입원 발생 시 즉각 콜백 계획이 배치안에 포함되어야 합니다. AI 병상 가동률 예측 시스템은 이런 상황을 사전에 경보하고, 관리자가 선제적으로 인력을 조정하도록 지원합니다. ________________"
