        "a": "신뢰도는 '완전히 신뢰'가 아닌 '보조 도구로서 활용'이 정확한 표현입니다. Valizadeh 등(2023)의 연구에서 Rayyan AI는 비적합 레코드를 제외하는 데 신뢰할 수 있었으나, 'Recall(재현율)은 가변적'이라는 한계가 확인되었습니다. 즉, 포함해야 할 논문을 놓칠(FN) 가능성이 있습니다. 이 위험을 최소화하기 위해 두 가지 안전장치가 권고됩니다. 첫째, Rayyan이 '제외 가능성 높음'으로 분류한 논문도 인간 검토자가 샘플링하여 확인합니다. 둘째, 두 명의 독립 검토자가 불일치를 해결하는 이중 검토 체계를 유지합니다. PRISMA 2020은 AI 도구 활용 시 이 과정을 Methods에 상세히 기술하도록 요구합니다. 결론적으로 Rayyan은 시간을 절약하는 강력한 도구이지만, 인간 감독 없이 단독으로 사용해서는 안 됩니다."
