      {
        "q": "'통계적으로 유의하지 않다(P>0.05)'는 것이 AI가 효과가 없다는 의미인가요?",
        "a": "아닙니다. 이 오해가 의료 연구에서 가장 흔한 통계적 오류 중 하나입니다. P>0.05는 '이 연구에서 귀무가설을 기각할 충분한 통계적 증거가 없다'는 의미일 뿐, 효과가 없다(Null Effect)는 것을 증명하지 않습니다. 가능한 이유는 두 가지입니다. 첫째, 표본이 너무 작아서 실제 차이가 있어도 통계적으로 탐지하지 못했을 수 있습니다(통계적 검정력 부족). 둘째, 실제로 효과가 미미하여 임상적으로도 의미가 없을 수 있습니다. 실습 B의 사망률 감소(18%→13%, P=0.08) 사례처럼, 5%p 감소는 임상적으로 의미 있을 수 있지만 표본 크기(250명)가 이 차이를 통계적으로 탐지하기에 충분하지 않았을 수 있습니다. 이것이 연구에서 AUC·SMD 같은 효과크기와 신뢰구간을 P값과 함께 보고해야 하는 이유입니다."
      },
      {
        "q": "간호사가 직접 간호 AI 연구를 수행하거나 참여할 수 있나요?",
        "a": "충분히 가능하며, 간호 AI 연구에서 간호사의 참여는 필수적입니다. 세 가지 수준의 참여가 있습니다. 첫째, 연구 데이터 생산자로서의 역할입니다. 간호사가 표준화된 용어로 정확하게 기록한 EMR 데이터가 AI 연구의 기반입니다. 둘째, 연구 협력자로서의 역할입니다. AI 연구팀에 임상 전문가로 참여하여 연구 질문 설정, 결과 임상 해석, 현장 타당성 검토를 담당합니다. 실제로 K-MIMIC 연구, IMPACT 사업단 등에서 간호 정보학 전문가들이 핵심 역할을 하고 있습니다. 셋째, 독립 연구자로서의 역할입니다. 간호 AI 체계적 문헌고찰, 간호 기록 NLP 연구, AI 도구 사용성 연구 등 간호 주도 AI 연구를 독립적으로 수행할 수 있습니다. JMIR Nursing(2025)에서도 미래 연구 방향으로 간호사를 대상으로 한 정량 연구를 제안하였습니다."
      },
      {
        "q": "AI 보조 체계적 문헌고찰에서 두 검토자 간 불일치(Disagreement)는 어떻게 해결하나요?",
        "a": "체계적 문헌고찰에서 두 검토자가 포함/제외 결정에 불일치할 때는 구조화된 과정으로 해결합니다. 먼저 Cohen's Kappa 계수로 검토자 간 일치도를 계산합니다(Kappa≥0.6: 양호한 일치). 불일치 논문에 대해 두 검토자가 토론하여 합의를 도출합니다. 합의가 어려울 경우 제3의 전문가(Senior Reviewer)가 최종 결정합니다. Rayyan은 이 과정을 시각적으로 지원합니다. AI를 활용한 경우에도 이 이중 검토 과정은 생략할 수 없습니다. AI 스크리닝은 검토자의 초기 작업을 효율화하지만, 검토자 간 불일치 해결 과정 자체를 대체할 수 없습니다."
      },
      {
        "q": "간호 연구에서 AUC 외에 어떤 성능 지표를 함께 확인해야 하나요?",
        "a": "AUC는 중요하지만 단독 사용 시 한계가 있습니다. The Lancet Digital Health(2025)에서도 AUC만으로 임상 의사결정 지원 모델을 평가하는 것의 한계를 지적했습니다. 함께 확인해야 할 지표들은 다음과 같습니다. 첫째, 보정 곡선(Calibration Curve): 예측 확률이 실제 발생 확률과 얼마나 일치하는가. 예를 들어 '70% 위험'이라고 예측했을 때 실제로 70% 환자에서 패혈증이 발생하는가. 둘째, 임상 유용성 지표(NRI, IDI): 기존 방법 대비 AI가 분류를 얼마나 개선했는가. 셋째, 결정 분석(Decision Analysis): 특정 임계값에서 이 AI를 사용하는 것이 임상적 이점을 주는가. 넷째, 민감도·특이도·PPV·NPV: AUC는 임계값 독립적이지만, 실제 임상에서는 특정 임계값에서의 성능이 중요합니다. ________________"
      }
