        "html": "<h4>빅데이터의 특성: 5V</h4><p><b>Volume</b>(규모) · <b>Velocity</b>(속도) · <b>Variety</b>(다양성) · <b>Veracity</b>(신뢰성) · <b>Value</b>(가치)</p><h4>한국 5대 공공 보건의료 빅데이터 비교</h4><ul><li><b>HIRA</b> (건강보험심사평가원): 전 국민 청구 데이터, 연간 수억 건. ICD-10 상병·처방·처치 포함 / <b>활력징후·검사 수치 없음</b>. 접근: opendata.hira.or.kr (환자표본 무료, 맞춤형 유료)</li><li><b>NHIS</b> (국민건강보험공단): 자격+검진+의료이용+장기요양. 표본코호트 5종, 건강검진 결과 포함, 장기 추적 가능</li><li><b>KNHANES</b> (질병관리청): 매년 약 1만 명, 400여 지표, 무료 공개. 생활습관+임상 측정+영양 포함 / 단면 조사 (종단 한계)</li><li><b>전국암등록</b> (국가암정보센터): 1980년~, 암 병기·생존·사망</li><li><b>K-MIMIC</b> (IMPACT 컨소시엄): ICU 임상 데이터, 협력 신청</li></ul><div class=\"callout warn\">연구 데이터 소스 선택의 첫 질문: <b>'내 연구 변수가 이 데이터에 실제로 존재하는가?'</b> — 활력징후 연구를 HIRA로 할 수 없는 이유입니다.</div>"
