        "html": "<h4>머신러닝의 세 가지 유형 × 간호 연구 적용</h4><ul><li><b>지도학습</b>: 레이블 있는 데이터로 예측 모델. 패혈증·재입원·낙상·욕창 예측 → Random Forest, XGBoost, 딥러닝</li><li><b>비지도학습</b>: 레이블 없이 구조 발견. 유사 임상 경과 환자 군집화, 번아웃 위험 집단 유형화</li><li><b>강화학습</b>: 시행착오로 최적 정책 학습. ICU 인슐린 용량 최적화, 간호 스케줄 동적 조정</li></ul><h4>ML 예측 모델 개발 7단계 파이프라인</h4><p>데이터 수집 → 전처리(Preprocessing) → 특성 공학(Feature Engineering) → 모델 학습 → 검증 → 성능 평가 → 배포·모니터링</p><h4>데이터 불균형(Class Imbalance) 문제</h4><div class=\"callout warn\">사건 발생률이 5%라면, 모든 환자를 '발생 안 함'으로 예측하는 무용지물 모델도 Accuracy 95%가 나옵니다. 발생률이 낮은 임상 데이터에서 Accuracy는 기만적 지표입니다.</div><ul><li><b>SMOTE</b>: 소수 클래스를 선형 보간으로 인공 생성하여 균형화</li><li><b>과적합(Overfitting)</b>: 훈련 데이터에 지나치게 최적화 → 테스트/외부 검증에서 성능 급락</li></ul><p><b>🇰🇷 국내 연구 사례</b>: HIRA 데이터 기반 재입원·낙상 예측 연구, AI 낙상예측 CDSS 임상 적용 연구(KOSMI 2025) 등이 진행되고 있습니다.</p>"
